#[using="Type"] Lemma pageup_low_k_sound : forall sg E e m j r,
  (sg = 1 \/ sg = -1)%Z ->
  (0 <= j <= 64)%Z -> m = (2 ^ j)%Z -> pageup_low_k sg e m = Some r ->
