#[using="Type"] Lemma lin_srange_exact : forall segs E M kn e lo hi,
  know_ok segs E M kn -> lin_srange kn e = Some (lo, hi) ->
  bv_unsigned (edenot E e) = (fst (lin_of e) + tden E (snd (lin_of e)))%Z.
