#[using="Type"] Lemma word_slice_bytes : forall w' d n (V : word), (d + n <= w')%nat -> (w' <= 8)%nat ->
  word_to_le_bytes n (ext_val false d n V) = firstn n (skipn d (word_to_le_bytes w' V)).
Proof.
