#[using="Type"] Lemma kword_cut_sound : forall E M (wb : expr) (wk : Z) w (V : word) kk w' v,
  flat E (SA wb wk) (Z.of_nat w) ->
  kentry_ok segs E M (KWord (SA wb kk) w' v) ->
  (Z.leb (kk + Z.of_nat w') wk || Z.leb (wk + Z.of_nat w) kk)%bool = false ->
